        msgs=re.split(r'\n\n(?=\d{4}-\d\d-\d\d \d\d:\d\d:\d\d )',t)[1:]
        for n,m in enumerate(msgs,1):
            m=m.rstrip('\n')
            hdr,_,body=m.partition('\n')
            ts=dt.datetime.strptime(hdr[:19],'%Y-%m-%d %H:%M:%S').replace(tzinfo=NY)
