               hash=hashlib.sha256(m.encode('utf-8')).hexdigest(),url=f'wechat/{base}#{n}'))
    return out
def chat_events():
    """interpreted facts from chats: list of dict(kind=..., msg=..., ...)"""
    ev=[];ctx={}
    for m in chat_messages():
        sup=m['sup'];b=m['body'];cn=m['ts'].astimezone(CN).date()
