           F(ref,'shipment/etd',b['etd'].isoformat()),F(ref,'shipment/eta',b['eta'].isoformat())]
        if s.get('status_w') is None or SRANK['booked']>SRANK[s['status_w']]: f.append(F(ref,'shipment/status','booked')); s['status_w']='booked'
