            if disc: R('discrepancy',f"{e['url']} ({ident}): "+'; '.join(x.strip() for x in disc.group(1).strip().split('\n')))
            for po in sorted({k[0] for k in s['lines']}):
                sh=[x for x in ships.values() if any(k[0]==po for k in x['lines'])]
