               F(C,'customs/entered_value',f"{g('Entered value'):.2f}"),F(C,'customs/duty',f'{duty:.2f}'),F(C,'customs/fees',f'{fees:.2f}'),F(C,'core/currency','USD')])

print('DRY' if DRY else 'APPLIED','tx',ntx,'facts',nfacts)
