                F(L,'po_line/quantity',str(it['qty'])),F(L,'po_line/unit_price',it['price'])]
        tx(h,f"supplier_docs/{p['f']}",f)
    elif kind=='qc':
        q=p['q'];h=H[p['f']];po=q['po'].strip()
