                if sf:
                    f+=sf; f.append(F(['po/number',po],'po/etd',pa['atd'].isoformat())); po_etd[po]=pa['atd'].isoformat()
        tx(e['hash'],e['url'],f)
    elif kind in ('eta_update','arrival'):
