        s=find_ship(hbl)
        if not s: R('unresolved',f"{e['url']}: unknown HBL {hbl}"); continue
        if kind=='eta_update': d=mon(re.search(r'revised ETA (.+?) for',e['body']).group(1)); f=[F(['shipment/hbl',hbl],'shipment/eta',at_port(d,s['pod']).isoformat())]
        else:
